// ---- Laporan masalah: ralat yang tidak dijangka dipaparkan sekali dengan butang Laporkan (tiada data kucing dihantar).
// Didaftarkan seawal mungkin; setiap rujukan kepada fungsi lain dilindungi supaya ia berfungsi walaupun app gagal dimuat.
let errShown=false,errInfo='';
function errT(t){try{return trs(t)}catch(e){return t}}
function errDev(){try{return [ENV.ios?'iPhone':ENV.and?'Android':'Lain',ENV.sa?'app':'pelayar',(UA.match(/OS (\d+[_.]\d+)|Android (\d+(\.\d+)?)/)||[]).slice(1).find(Boolean)||''].filter(Boolean).join(' ').replace(/_/g,'.')}catch(e){return ''}}
function onErr(msg,src,line,col){try{msg=String(msg||'');
// Abaikan ralat skrip luar (fon, analytics, sambungan pelayar) yang tidak menjejaskan app.
if(!msg||/^Script error\.?$/i.test(msg)||/ResizeObserver loop/i.test(msg))return;
if(src&&!/^\/(app\.js|index\.html)?([?#]|$)/.test(String(src).replace(/^https?:\/\/[^/]+/,'')))return;
errInfo=[errDev(),msg+(line?' @'+line+':'+(col||0):'')].filter(Boolean).join(' · ').replace(/\s+/g,' ').slice(0,300);
if(errShown||typeof document==='undefined'||!document.body)return;errShown=true;
let b=document.getElementById('err');if(!b){b=document.createElement('div');b.id='err';b.className='err';b.setAttribute('role','alertdialog');document.body.appendChild(b)}
b.innerHTML=`<b>${errT('Ada masalah dalam app')}</b><p>${errT('Data anda selamat dan tidak diubah. Bantu kami membaikinya dengan menghantar laporan ringkas.')}</p><div class="acts"><button class="btn" type="button">${errT('Laporkan')}</button><button class="btn g" type="button">${errT('Muat semula')}</button><button class="btn g" type="button">${errT('Tutup')}</button></div>`;
const [r,l,c]=b.querySelectorAll('button');r.addEventListener('click',errReport);l.addEventListener('click',()=>location.reload());c.addEventListener('click',errClose)}catch(e){}}
function errReport(){let u='';try{u=fbUrl('Ralat: '+errInfo)}catch(e){}
if(u){try{open(u,'_blank','noopener')}catch(e){}}else{try{toast('Borang maklum balas belum tersedia. Cuba lagi kemudian.')}catch(e){}}}
function errClose(){const b=document.getElementById('err');if(b)b.remove();errShown=false}
try{addEventListener('error',e=>onErr(e&&e.message,e&&e.filename,e&&e.lineno,e&&e.colno));addEventListener('unhandledrejection',e=>{const r=e&&e.reason;onErr(r&&r.message?r.message:String(r),'',0,0)})}catch(e){}

const SK='kucingku-settings-v1';let SET={lang:'ms',bk:30,unit:'auto',scheme:'sakura',mode:'system'};
const SCH={sakura:'Sakura',langit:'Langit',pudina:'Pudina',lavender:'Lavender',aprikot:'Aprikot'},MD={system:'Sistem',light:'Cerah',dark:'Gelap'};
let persistedState=JSON.stringify(S),storageReadError=false,rawStorage='';
function loadSet(){try{const r=JSON.parse(localStorage.getItem(SK)||'null');if(r&&typeof r==='object'&&r.v===1){if(r.lang==='en')SET.lang='en';if([0,14,30,60].includes(r.bk))SET.bk=r.bk;if(['auto','g','kg'].includes(r.unit))SET.unit=r.unit;if(Object.keys(SCH).includes(r.scheme))SET.scheme=r.scheme;if(Object.keys(MD).includes(r.mode))SET.mode=r.mode}}catch(e){}}
const isDark=()=>SET.mode==='dark'||(SET.mode==='system'&&typeof matchMedia==='function'&&!!matchMedia('(prefers-color-scheme: dark)').matches);
function applyTheme(){const e=document.documentElement;if(!e||!e.setAttribute)return;e.setAttribute('data-scheme',SET.scheme);e.setAttribute('data-mode',isDark()?'dark':'light');try{const m=document.querySelector('meta[name="theme-color"]');if(m&&m.setAttribute&&typeof getComputedStyle==='function'){const c=getComputedStyle(e).getPropertyValue('--bg').trim();if(c)m.setAttribute('content',c)}}catch(x){}}
function saveSet(){try{localStorage.setItem(SK,JSON.stringify({v:1,...SET}));return true}catch(e){return false}}
function save(recover=false){
try{
if(storageReadError&&!recover)throw new Error('unreadable-storage');
const json=JSON.stringify(S);localStorage.setItem(K,json);persistedState=json;storageReadError=false;return true;
}catch(e){
S=JSON.parse(persistedState);
toast(storageReadError?'Data storan tidak dapat dibaca. Export salinan asal atau import backup dahulu.':'Gagal menyimpan. Data terdahulu dikekalkan; cuba lagi atau buat backup.');
return false;
}}

