const LOC=()=>SET.lang==='en'?'en-MY':'ms-MY';
const pl=(n,w)=>n+' '+w+(+n===1?'':'s');
const TS={berat:'weight',vaksin:'vaccine','ubat cacing / kutu':'deworming / flea','lawatan vet':'vet visit',kesihatan:'health note'};
const RU=[[/^Hari lahir (.+)! (\d+) tahun$/,(m,n,y)=>n+"'s birthday! "+pl(y,'year')],[/^(\d+) tahun (.+) bersama anda$/,(m,y,n)=>pl(y,'year')+' with '+n],[/^(\d+) tahun bersama!$/,(m,y)=>pl(y,'year')+' together!'],[/^(.+) \((\d+) tahun bersama\)$/,(m,d,y)=>d+' ('+pl(y,'year')+' together)'],[/^Mula dibela (.+)$/,(m,d)=>'Adopted '+d],[/^Sejak (.+)$/,(m,d)=>'Since '+d],[/^±(\d+) hari$/,(m,n)=>'±'+pl(n,'day')],[/^(\d+) hampir habis$/,(m,n)=>n+' running low'],[/^Anggaran habis dalam ±(\d+) hari$/,(m,n)=>'Likely to run out in ±'+pl(n,'day')],[/^Biasanya tahan ±(\d+) hari$/,(m,n)=>'Usually lasts ±'+pl(n,'day')],[/^Belum cukup data\. Anggaran ikut (\d+) hari\.$/,(m,n)=>'Not enough data yet. Estimate based on '+pl(n,'day')+'.'],[/^dibeli (.+)$/,(m,x)=>'bought '+x],[/^Dah beli: (.+)$/,(m,x)=>'Bought: '+trs1(x)],[/^Kongsi kad (.+)$/,(m,n)=>'Share '+n+"'s card"],[/^(\d+) tahun(?: (\d+) bulan)?$/,(m,y,mo)=>pl(y,'year')+(mo?' '+pl(mo,'month'):'')],[/^(\d+) bulan$/,(m,n)=>pl(n,'month')],[/^(\d+) minggu$/,(m,n)=>pl(n,'week')],[/^(\d+) perlu perhatian$/,(m,n)=>n+' need'+(+n===1?'s':'')+' attention'],[/^Berat (turun|naik) (\d+)% dalam sebulan$/,(m,a,n)=>'Weight '+(a==='turun'?'dropped':'rose')+' '+n+'% in a month'],[/^(.+) → (.+)\. Pertimbangkan untuk jumpa vet\.$/,(m,a,b)=>a+' → '+b+'. Consider seeing a vet.'],[/^(.+) → (.+)\. Bincang dengan vet tentang makanan dan berat ideal\.$/,(m,a,b)=>a+' → '+b+'. Talk to your vet about food and ideal weight.'],[/^Belum timbang (\d+) (hari|minggu)$/,(m,n,u)=>'Not weighed for '+pl(n,u==='hari'?'day':'week')],[/^Untuk umur ini, timbang (.+)\.$/,(m,x)=>'At this age, weigh '+trs1(x.charAt(0).toUpperCase()+x.slice(1)).toLowerCase()+'.'],[/^(Vaksin core|Ubat cacing) lewat (\d+) hari$/,(m,a,n)=>(a==='Vaksin core'?'Core vaccine':'Deworming')+' overdue by '+pl(n,'day')],[/^Ditimbang (.+)$/,(m,x)=>'Weighed '+x],[/^(.+):$/,(m,x)=>x+':'],[/^(\d+) rekod$/,(m,n)=>pl(n,'record')],[/^(\d+) acara$/,(m,n)=>pl(n,'event')],[/^(±)?(\d+) minggu \((?:(\d+) bulan )?(\d+) hari\)$/,(m,p,w,mo,d)=>(p||'')+pl(w,'week')+' ('+(mo?pl(mo,'month')+' ':'')+pl(d,'day')+')'],
[/^Lewat (\d+) hari$/,(m,n)=>'Overdue '+pl(n,'day')],[/^(\d+) hari lagi$/,(m,n)=>pl(n,'day')+' left'],[/^(\d+) hari$/,(m,n)=>pl(n,'day')],
[/^(±?\d+) minggu lagi$/,(m,n)=>n+' weeks left'],[/^Setiap (\d+) hari$/,(m,n)=>'Every '+n+' days'],
[/^(\d+) ekor kucing dalam jagaan$/,(m,n)=>pl(n,'cat')+' in your care'],[/^(\d+) klinik disimpan$/,(m,n)=>pl(n,'clinic')+' saved'],[/^(\d+) rekod berat disimpan$/,(m,n)=>pl(n,'weight record')+' saved'],
[/^Tambah rekod (.+)$/,(m,x)=>'Add '+(TS[x]||x)+' record'],[/^Belum ada rekod (.+)\.$/,(m,x)=>'No '+(TS[x]||x)+' records yet.'],[/^Edit (.+)$/,(m,x)=>'Edit '+(TS[x.toLowerCase()]||x)+' record'],
[/^(Vaksin core|Vaksin rabies|Ubat cacing|Timbang berat|Temujanji vet) (.+)$/,(m,a,n)=>({'Vaksin core':'Core vaccine','Vaksin rabies':'Rabies vaccine','Ubat cacing':'Deworming','Timbang berat':'Weigh-in','Temujanji vet':'Vet appointment'})[a]+' '+n],
[/^Import (\d+) kucing, (\d+) rekod dan (\d+) klinik\? Semua data semasa akan diganti\.$/,(m,c,r,v)=>'Import '+pl(c,'cat')+', '+pl(r,'record')+' and '+pl(v,'clinic')+'? All current data will be replaced.'],[/^Berat (.+) mesti antara 1 g hingga 30 kg$/,(m,n)=>'Weight for '+n+' must be between 1 g and 30 kg'],[/^(\d+) hari ini$/,(m,n)=>n+' due today'],[/^(\d+) perkara hari ini$/,(m,n)=>pl(n,'item')+' today'],[/^(\d+) lewat$/,(m,n)=>n+' overdue'],[/^(\d+) daripada (\d+) selesai$/,(m,a,b)=>a+' of '+b+' done'],
[/^Direkod: (.+)$/,(m,x)=>'Recorded as: '+x],[/^Umur: (.+)$/,(m,x)=>'Age: '+trs1(x)],[/^Seterusnya (.+)$/,(m,x)=>'Next '+x],[/^Terakhir (.+)$/,(m,x)=>'Last '+x],[/^terakhir (.+)$/,(m,x)=>'last '+x],
[/^Selesai (.+)$/,(m,x)=>'Done '+x],[/^Cadangan (.+)$/,(m,x)=>'Suggested '+x],[/^lepas: (.+)$/,(m,x)=>'last: '+x],[/^Terakhir: (.+)$/,(m,x)=>'Last: '+x],
[/^([+-][\d.]+ (?:g|kg)) sejak timbangan sebelum ini$/,(m,x)=>x+' since the last weigh-in'],[/^Klinik utama: (.+)$/,(m,x)=>'Main clinic: '+x],
[/^Dijana oleh Kucingku pada (.+)\. Panduan sahaja dan bukan pengganti nasihat doktor haiwan\.$/,(m,d)=>'Generated by Kucingku on '+d+'. General guidance only, not a substitute for veterinary advice.'],
[/^Apa yang baharu dalam v(.+)$/,(m,v)=>"What's new in v"+v],[/^Kucingku v(\S+) · (.+)$/,(m,v,d)=>'Kucingku v'+v+' · '+d],[/^Halaman (\d+) \/ (\d+)$/,(m,a,b)=>'Page '+a+' of '+b],[/^Dijana (\d.*)$/,(m,d)=>'Generated '+d],[/^(.+) \(anggaran\)$/,(m,x)=>x+' (estimated)'],[/^([♂♀]) (.+)$/,(m,s,x)=>s+' '+trs1(x)],[/^✓ (.+)$/,(m,x)=>'✓ '+trs1(x)]];
const trs1=x=>{if(EN[x]!==undefined)return EN[x];for(const [r,f] of RU){const m=x.match(r);if(m)return f(...m)}return x};
const trs=x=>{if(SET.lang!=='en')return x;if(EN[x]!==undefined)return EN[x];return x.includes(' · ')?x.split(' · ').map(trs1).join(' · '):trs1(x)};
function tx(root){if(SET.lang!=='en'||!root||!root.querySelectorAll)return;
root.querySelectorAll('option:not([value])').forEach(o=>o.setAttribute('value',o.textContent));
const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),ns=[];while(w.nextNode())ns.push(w.currentNode);
ns.forEach(n=>{const p=n.parentNode&&n.parentNode.nodeName;if(p==='STYLE'||p==='SCRIPT'||p==='TEXTAREA')return;const v=n.nodeValue,c=v.trim();if(!c)return;const r=trs(c);if(r!==c)n.nodeValue=v.replace(c,()=>r)});
root.querySelectorAll('[placeholder],[aria-label],[alt],[title]').forEach(e=>['placeholder','aria-label','alt','title'].forEach(a=>{if(e.hasAttribute(a)){const v=e.getAttribute(a),r=trs(v);if(r!==v)e.setAttribute(a,r)}}))}
const bkOld=()=>SET.bk>0&&(!S.bk||Date.now()-S.bk>SET.bk*864e5);
let ssub='';
const UN={auto:'Auto',g:'Gram (g)',kg:'Kilogram (kg)'};
const sSub=(k,i,t,sub)=>`<button class="row mr" data-action="setGo" data-v="${k}"><svg viewBox="0 0 24 24" aria-hidden="true">${I[i]}</svg><span><b>${t}</b><span class="mute">${sub}</span></span><span class="chev">›</span></button>`;
function setv(){const seg=(on,act,v,l)=>`<button class="${on?'on':''}" data-action="${act}" data-v="${v}">${l}</button>`;
const back=ssub?`<button class="bk" data-action="setGo" data-v="">‹ Setting</button>`:`<button class="bk" data-action="go" data-view="more">‹ Lagi</button>`,H=t=>back+`<h2 style="margin-top:12px">${t}</h2>`;
if(!ssub)return H('Setting')+sSub('umum','set','Umum',(SET.lang==='en'?'English':'Bahasa Melayu')+' · '+UN[SET.unit])+sSub('tema','pal','Tema',trs(SCH[SET.scheme])+' · '+trs(MD[SET.mode]))+sSub('peringatan','bell','Peringatan','Backup · '+(SET.bk?SET.bk+' hari':'Mati'))+sSub('data','db','Data',S.bk?'Backup terakhir · '+fd(iso(new Date(S.bk))):'Belum ada backup')+sSub('tentang','info','Tentang','v'+VER+' · Maklum balas');
if(ssub==='umum')return H('Umum')+`<div class="card"><b>Bahasa</b><div class="seg">${seg(SET.lang==='ms','setLang','ms','Bahasa Melayu')}${seg(SET.lang==='en','setLang','en','English')}</div></div><div class="card"><b>Unit berat</b><p class="mute">Auto: gram di bawah 1 kg, kg selepas itu.</p><div class="seg">${['auto','g','kg'].map(k=>seg(SET.unit===k,'setUnit',k,UN[k])).join('')}</div></div>`;
if(ssub==='tema')return H('Tema')+`<div class="card"><b>Mod paparan</b><p class="mute">Sistem mengikut tetapan cerah atau gelap pada telefon anda.</p><div class="seg">${Object.keys(MD).map(k=>seg(SET.mode===k,'setMode',k,MD[k])).join('')}</div></div><div class="card"><b>Skema warna</b><p class="mute">Pilih warna pastel untuk app.</p><div class="tsw">${Object.keys(SCH).map(k=>`<button class="${SET.scheme===k?'on':''}" data-action="setScheme" data-v="${k}" aria-pressed="${SET.scheme===k}"><i class="s-${k}">${SET.scheme===k?'✓':''}</i>${SCH[k]}</button>`).join('')}</div></div>`;
if(ssub==='peringatan')return H('Peringatan')+`<div class="card"><b>Peringatan backup</b><p class="mute">Tunjukkan peringatan jika sudah lama tidak membuat backup.</p><div class="seg">${[[14,'14 hari'],[30,'30 hari'],[60,'60 hari'],[0,'Mati']].map(([n,l])=>seg(SET.bk===n,'setBk',n,l)).join('')}</div></div>`;
if(ssub==='log')return logv();
if(ssub==='data')return H('Data')+bkBody()+`<div class="card"><b>Padam semua data</b><p class="mute">Semua kucing, rekod dan klinik akan dipadam daripada telefon ini. Buat backup dahulu jika anda mungkin memerlukannya.</p><div class="acts"><button class="btn r" data-action="wipe">Padam semua data</button></div></div>`;

return H('Tentang')+`<button class="row mr" data-action="setGo" data-v="log"><svg viewBox="0 0 24 24" aria-hidden="true">${I.doc}</svg><span><b>Senarai perubahan</b><span class="mute">Apa yang baharu dalam setiap versi · v${VER}</span></span><span class="chev">›</span></button><button class="row mr" data-action="fbForm"><svg viewBox="0 0 24 24" aria-hidden="true">${I.chat}</svg><span><b>Maklum balas</b><span class="mute">Cadangan, masalah atau soalan</span></span><span class="chev">›</span></button><div class="card"><b>Privasi</b><p class="mute">Data kucing anda disimpan di telefon ini sahaja dan tidak dihantar ke mana-mana. Kucingku hanya mengira bilangan lawatan secara tanpa nama, tanpa cookie, untuk memahami penggunaan app.</p></div><div class="card"><b>Kucingku</b><p class="mute">Kucingku v${VER}</p><p class="mute">Panduan dalam app ini bersifat umum dan bukan nasihat veterinar. Sahkan sentiasa dengan doktor haiwan anda.</p><p class="mute" style="margin-top:12px">Rujukan peraturan jadual</p><p><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC7166872/" target="_blank" rel="noopener">WSAVA Vaccination Guidelines</a></p><p><a href="https://www.esccap.org/uploads/docs/21f9zve8_0778_ESCCAP_GL1__Worm_Management_Scheme_Fact_Sheet__Cats_v8.pdf" target="_blank" rel="noopener">ESCCAP: Worm control in cats</a></p><p><a href="https://www.valleyvet.com/animal-health-articles/worming-schedule-for-puppies-dogs-kittens-and-cats/" target="_blank" rel="noopener">Worming schedule for kittens and cats</a></p><p><a href="https://www.dvm360.com/view/evaluating-normal-neonates-proceedings-0" target="_blank" rel="noopener">Evaluating normal neonates</a></p></div>`}
function goData(){view='set';ssub='data';nav();scrollTo(0,0);render()}
function setGo(k){ssub=k;nav();scrollTo(0,0);render()}
const setPref=(k,v,ok)=>{const o=SET[k];SET[k]=v;if(saveSet())ok();else{SET[k]=o;toast('Gagal menyimpan tetapan')}};
function setUnit(k){if(!['auto','g','kg'].includes(k))return;setPref('unit',k,()=>{render();toast('Tetapan disimpan')})}
function setLang(l){if(!['ms','en'].includes(l))return;setPref('lang',l,()=>{if(document.documentElement)document.documentElement.lang=l;render();toast('Bahasa ditukar')})}
function setScheme(k){if(!Object.keys(SCH).includes(k))return;setPref('scheme',k,()=>{applyTheme();render();toast('Tema ditukar')})}
function setMode(k){if(!Object.keys(MD).includes(k))return;setPref('mode',k,()=>{applyTheme();render();toast('Tema ditukar')})}
function setBk(n){if(![0,14,30,60].includes(n))return;setPref('bk',n,()=>{render();toast('Tetapan disimpan')})}
function wipe(){ask('Padam semua data? Tindakan ini tidak boleh dibatalkan.','Padam semua',()=>{S={version:SCHEMA_VERSION,cats:[],recs:[],vets:[],bk:0};if(!save(true)){render();return}go('home');toast('Semua data dipadam')})}
function doneToday(){const T=td(),seen=new Set(),o=[];S.recs.slice().reverse().forEach(r=>{if(r.date!==T||!['berat','vaksin','cacing'].includes(r.type))return;const c=cat(r.cat);if(!c)return;const k=c.id+r.type;if(seen.has(k))return;seen.add(k);o.push({c,t:r.type,ti:r.type==='vaksin'&&!isCore(r)?'Vaksin rabies':TL[r.type],l:r.type==='berat'?fw(r.val):r.name||''})});careAll().forEach(({c,x})=>{if(x.dn===T)o.unshift({c,t:'jagaan',ti:careN(x),l:civL(x.iv),cid:x.id})});return o.reverse()}
const frow=(x,done)=>{const{c,t,l,date,d}=x,tt=x.ti||TL[t],j=t==='jagaan',at=j?`data-action="${done?'careUndo':'careDone'}" data-cat="${c.id}" data-id="${x.cid}"`:`data-action="${done?'openCat':'task'}" data-id="${c.id}" data-${done?'tab':'type'}="${t}"`;return `<button class="row fr${done?' dn':''}" ${at}><i class="cb">${done?'✓':''}</i>${av(c)}<span><b>${j?`<span>${esc(tt)}</span>`:tt} ${esc(c.name)}</b><span class="mute">${esc(l)}${done?'':' · '+(t==='lawatan'||j?'':'±')+fd(date)}</span></span><span class="pill ${!done&&d<0?'bad':''}">${done?'Selesai':rel(d)}</span></button>`};
function focus(){const k=tasks().filter(x=>x.d<=0),dn=doneToday(),n=k.length,l=k.filter(x=>x.d<0).length,t=n+dn.length;
const head=!t?'Tiada tugasan hari ini':n?`${n} perkara hari ini`+(l?` · ${l} lewat`:''):'Semua beres hari ini';
return `<div class="card fc"><div class="fh"><b>Fokus hari ini</b><span class="mute">${head}</span></div>`+(t?`<div class="prog"><i style="width:${Math.round(dn.length/t*100)}%"></i></div><small class="mute">${dn.length} daripada ${t} selesai</small><div style="margin-top:10px">${k.map(x=>frow(x,0)).join('')}${dn.map(x=>frow(x,1)).join('')}</div>`:'')+`</div>`}
function nextAppt(){const T=td();return S.recs.filter(r=>r.type==='lawatan'&&r.date>=T&&cat(r.cat)).sort((a,b)=>(a.date+(a.time||'99:99')).localeCompare(b.date+(b.time||'99:99')))[0]}
function apptCard(){const r=nextAppt();if(!r)return `<div class="card ap em"><div><b>Temujanji seterusnya</b><p class="mute">Tiada temujanji akan datang</p></div><button class="btn g" data-action="addAppt">Tambah temujanji</button></div>`;
const c=cat(r.cat),v=S.vets.find(x=>x.id===r.clinic),d=dif(td(),r.date);
return `<div class="card ap"><div class="ah"><b>Temujanji seterusnya</b><span class="pill${d===0?' hot':''}">${rel(d)}</span></div><button class="row" data-action="openCat" data-id="${c.id}" data-tab="lawatan">${av(c)}<span><b>${esc(r.name)}</b><span class="mute">${esc(c.name)}</span></span></button><p class="when">${fd(r.date)}${r.time?' · '+r.time:''}</p>${v?`<p class="mute">${esc(v.name)}</p>`:''}<div class="acts">${v&&v.tel?`<a class="btn ic" href="tel:${esc(v.tel.replace(/\s/g,''))}"><svg viewBox="0 0 24 24" aria-hidden="true">${I.phone}</svg>Telefon</a>`:''}${v?`<a class="btn g ic" href="${esc(vlink(v))}" target="_blank" rel="noopener"><svg viewBox="0 0 24 24" aria-hidden="true">${I.pin}</svg>Peta</a>`:''}<button class="btn g ic" data-action="openCat" data-id="${c.id}" data-tab="lawatan"><svg viewBox="0 0 24 24" aria-hidden="true">${I.go}</svg>Lihat</button><button class="btn g ic" data-action="calOne" data-id="${r.id}"><svg viewBox="0 0 24 24" aria-hidden="true">${I.jd}</svg>Kalendar</button></div></div>`}
function addAppt(){if(S.cats.length===1){openCat(S.cats[0].id,'lawatan');recForm();return}sheet(`<h2>Pilih kucing</h2>${S.cats.map(c=>`<button class="row" data-action="pickRec" data-id="${c.id}" data-tab="lawatan">${av(c)}<span><b>${esc(c.name)}</b></span></button>`).join('')}`)}
const wTrend=id=>{const a=newest(S.recs.filter(r=>r.cat===id&&r.type==='berat'));return a.length?{w:a[0].val,d:a[1]?a[0].val-a[1].val:0}:null};
function catStat(c,k){if(!c.dob)return{t:'Isi tarikh lahir',k:'warn'};const m=k.filter(x=>x.c.id===c.id),l=m.filter(x=>x.d<0).length,t=m.filter(x=>x.d===0).length;return l?{t:l+' lewat',k:'bad'}:t?{t:t+' hari ini',k:'hot'}:{t:'Terkini',k:'ok'}}
function catCards(k){return `<div class="cch"><h2 style="margin:0">Kucing</h2><button class="x" data-action="go" data-view="cats">Lihat semua</button></div><div class="cc2">${S.cats.map(c=>{const st=catStat(c,k),w=wTrend(c.id);return `<button class="kc2${c.sex==='Jantan'?' j':' b'}" data-action="openCat" data-id="${c.id}">${av(c)}<b class="kn">${esc(c.name)}</b><span class="mute">${ageT(c)||'Tarikh lahir belum diisi'}</span><span class="wt">${w?`<b>${fw(w.w)}</b>${w.d?` <em class="${w.d<0?'dn2':'up'}">${w.d<0?'▼':'▲'} ${fw(Math.abs(w.d))}</em>`:''}`:'<span class="mute">Belum ditimbang</span>'}</span><span class="pill ${st.k}">${st.t}</span></button>`}).join('')}<button class="kc2 add" data-action="catForm"><span class="plus">+</span><b class="kn">Tambah kucing</b></button></div>`}
function qactions(){const v=S.vets.find(x=>x.main&&x.tel);
return `<div class="qa"><button data-action="quickW"><svg viewBox="0 0 24 24" aria-hidden="true">${I.scale}</svg><b>Timbang cepat</b></button><button data-action="addRec"><svg viewBox="0 0 24 24" aria-hidden="true">${I.plus}</svg><b>Tambah rekod</b></button>${v?`<a href="tel:${esc(v.tel.replace(/\s/g,''))}"><svg viewBox="0 0 24 24" aria-hidden="true">${I.phone}</svg><b>Telefon vet</b><small>${esc(v.name)}</small></a>`:`<button data-action="vetForm"><svg viewBox="0 0 24 24" aria-hidden="true">${I.vet}</svg><b>Tambah vet</b></button>`}</div>`}
function addRec(){if(S.cats.length===1)return recType(S.cats[0].id);sheet(`<h2>Pilih kucing</h2>${S.cats.map(c=>`<button class="row" data-action="recType" data-id="${c.id}">${av(c)}<span><b>${esc(c.name)}</b></span></button>`).join('')}`)}
function recType(id){sheet(`<h2>Jenis rekod</h2><p class="mute" style="margin:-8px 0 12px">${esc(cat(id).name)}</p>${Object.keys(T).map(k=>`<button class="row" data-action="pickRec" data-id="${id}" data-tab="${k}"><span><b>${T[k]}</b></span></button>`).join('')}`)}
function go(v){view=v;ssub='';nav();scrollTo(0,0);render()}
// ---- Butang Back (Android): setiap skrin dan borang ialah satu entri sejarah, jadi Back menutup borang
// atau kembali ke skrin sebelumnya, bukan keluar dari app.
const HS=typeof history!=='undefined'&&!!history.pushState&&!!history.replaceState;
const VIEWS=['home','cats','cat','jd','more','vet','exp','stok','cal','set'];
let shEntry=false,backPending=false,skipPop=0;
const navState=()=>({v:view,cid,tab,ssub});
function nav(){if(!HS)return;try{const n=navState();
if(backPending){backPending=false;history.replaceState(n,'');return}
const o=history.state;if(o&&!o.sh&&o.v===n.v&&o.cid===n.cid&&o.ssub===n.ssub){history.replaceState(n,'');return}
history.pushState(n,'')}catch(e){}}
function onPop(e){if(skipPop>0){skipPop--;return}
const sh=$('#sh');if(!sh.hidden){sh.hidden=true;shEntry=false;return}
const s=e&&e.state;if(!s||typeof s!=='object'||!VIEWS.includes(s.v))return;
view=s.v;cid=s.cid;tab=TABS.some(x=>x[0]===s.tab)?s.tab:'berat';ssub=typeof s.ssub==='string'?s.ssub:'';
if(view==='cat'&&!cat(cid))view='cats';scrollTo(0,0);render()}
const LS=[['Anak kucing','0–6 bulan',0,'Membesar pantas. Fokus pada vaksin, ubat cacing dan makanan anak kucing.'],['Remaja','6 bulan–2 tahun',6,'Tenaga tinggi dan suka meneroka. Masa untuk fikir tentang pemandulan.'],['Dewasa','2–6 tahun',24,'Berat dan tenaga stabil. Pemeriksaan vet setahun sekali.'],['Matang','7–10 tahun',84,'Pantau berat, gigi dan selera makan dengan lebih rapi.'],['Senior','11–14 tahun',132,'Pemeriksaan vet lebih kerap, kira-kira setiap 6 bulan.'],['Warga emas','15 tahun ke atas',180,'Jagaan penuh kasih dan pemeriksaan kerap.']];
const TIPS=[['Vaksin dan ubat cacing ikut jadual','Makanan khas kitten dan air bersih sentiasa','Timbang berat setiap hari hingga sapih, kemudian sekurang-kurangnya setiap minggu'],['Banyakkan masa bermain bersama','Fikir tentang pemandulan (neuter/spay)','Tukar makanan secara berperingkat bila sesuai'],['Pemeriksaan vet setahun sekali','Jaga berat badan yang ideal','Booster vaksin ikut nasihat vet'],['Pantau berat dan selera makan','Jaga kebersihan gigi','Pemeriksaan vet secara berkala'],['Pemeriksaan vet kira-kira setiap 6 bulan','Pantau pengambilan air dan berat','Sediakan tempat tidur yang selesa'],['Pemeriksaan vet yang lebih kerap','Pilih makanan yang mudah dicerna','Beri persekitaran yang tenang dan selesa']];
const iso=x=>new Date(x-x.getTimezoneOffset()*6e4).toISOString().slice(0,10);
const stI=c=>{if(!c.dob||dif(c.dob,td())<0)return -1;const m=mAge(c.dob);let i=0;LS.forEach((x,j)=>{if(m>=x[2])i=j});return i};
const stN=c=>{const i=stI(c);return i<0?'':LS[i][0]};
const lsT=c=>{const i=stI(c);if(i<0)return'';const a=new Date(c.dob+'T00:00'),b=new Date(td()+'T00:00'),p=c.dobx==='Anggaran'?'±':'',nx=LS[i+1];let note='';
if(nx){const x=new Date(addM(c.dob,nx[2])+'T00:00'),w=Math.max(0,Math.ceil((x-b)/6048e5));note=`<div class="nx"><div>Fasa seterusnya<br><b>${nx[0]}</b></div><span>${p}${fd(iso(x))}<br>${p}${w} minggu lagi</span></div>`}
return `<h2>Kitaran hidup</h2><div class="card"><div class="lc">${LS.map((x,j)=>`<div class="ls${j<i?' d':''}${j===i?' n':''}"><i></i><span><b>${x[0]}</b><small>${x[1]}</small></span>${j===i?'<span class="pill">Sekarang</span>':''}</div>`).join('')}</div>${note}<div class="tips"><b>Petua jagaan</b>${TIPS[i].map(t=>`<div class="tp">${t}</div>`).join('')}<small>Panduan umum. Rujuk doktor haiwan untuk nasihat khusus.</small></div></div>`};
const ageT=c=>c.dob?(c.dobx==='Anggaran'?'±':'')+age(c.dob):'';

// Kongsi kad profil sebagai gambar 1080×1350 (v1.9.3). Microchip dan maklumat vet tidak pernah dimasukkan.
const KF=[['umur','Umur'],['baka','Baka'],['vaksin','Status vaksin'],['berat','Berat'],['warna','Warna / corak']];
let kOpt={id:'',m:'profil',f:['umur','baka','vaksin']},kBusy=false;
function kAge(c){if(!c.dob)return'';const d=dif(c.dob,td()),m=mAge(c.dob);if(d<0)return'';if(m<3)return Math.floor(d/7)+' minggu';if(m<12)return m+' bulan';const y=Math.floor(m/12),r=m%12;return y+' tahun'+(r?' '+r+' bulan':'')}
function kVax(c){const p=plan(c);return p&&p.v.last&&dif(p.v.d,td())<=0?'✓ Terkini':''}
function kFields(c){const w=lastW(c.id);return{umur:kAge(c),baka:c.breed||'',vaksin:kVax(c),berat:w?fw(w.val):'',warna:c.pattern||''}}
function kcard(c,o){const j=c.sex==='Jantan',v=kFields(c),st=stN(c),sx=c.sex==='Jantan'?'♂ Jantan':c.sex==='Betina'?'♀ Betina':'',rib=[sx,st].filter(Boolean).join(' · '),dc=j?'★':'♥';
const deco=`<i class="kd d1">${dc}</i><i class="kd d2">${dc}</i><i class="kd d3">${dc}</i>`,foot='<div class="kpm"><span>Dibuat dengan</span> <b>Kucingku</b> · <span>app percuma rekod kucing</span></div>';
if(o.m==='bela'&&c.adopt){const n=yrs(c.adopt);return `<div class="kp kl${j?' j':''}">${deco}<i class="kcf c1"></i><i class="kcf c2"></i><i class="kcf c3"></i><i class="kcf c4"></i><div class="kpt">${n?`${n} tahun bersama!`:'Ahli keluarga baharu!'}</div>${av(c)}<div class="kpn">${esc(c.name)}</div><div class="kpa kps2">Sejak ${fd(c.adopt)}</div>${rib?`<div class="kpr">${rib}</div>`:''}${foot}</div>`}
if(o.m==='lahir')return `<div class="kp kl${j?' j':''}">${deco}<i class="kcf c1"></i><i class="kcf c2"></i><i class="kcf c3"></i><i class="kcf c4"></i><div class="kpt">Selamat hari lahir!</div>${av(c)}<div class="kpn">${esc(c.name)}</div>${v.umur?`<div class="kpa">${v.umur}</div>`:''}${rib?`<div class="kpr">${rib}</div>`:''}${foot}</div>`;
const rows=KF.filter(([k])=>o.f.includes(k)&&v[k]).map(([k,l])=>`<div><span>${l}</span><b>${esc(v[k])}</b></div>`).join('');
const n=KF.filter(([k])=>o.f.includes(k)&&v[k]).length;return `<div class="kp${j?' j':''}${n>3?' kcmp':''}">${deco}${av(c)}<div class="kpn">${esc(c.name)}</div>${rib?`<div class="kpr">${rib}</div>`:''}${rows?`<div class="kpf">${rows}</div>`:''}${foot}</div>`}
function kFit(){const w=$('.kpw'),p=$('.kps');if(w&&p&&w.clientWidth&&p.style)p.style.transform='scale('+(w.clientWidth/1080)+')'}
function cardForm(id){const c=cat(id);if(!c)return;if(kOpt.id!==id)kOpt={id,m:'profil',f:['umur','baka','vaksin']};if((!c.dob&&kOpt.m==='lahir')||(!c.adopt&&kOpt.m==='bela'))kOpt.m='profil';const v=kFields(c);
const seg=(m,l)=>`<button class="${kOpt.m===m?'on':''}" data-action="kMode" data-v="${m}">${l}</button>`;
sheet(`<h2>Kongsi kad ${esc(c.name)}</h2><p class="mute">Gambar 1080 × 1350, sesuai untuk WhatsApp, Threads dan IG Story.</p>${c.dob||c.adopt?`<div class="seg ksg">${seg('profil','Kad profil')}${c.dob?seg('lahir','Hari lahir'):''}${c.adopt?seg('bela','Hari dibela'):''}</div>`:''}<div class="kpw"><div class="kps">${kcard(c,kOpt)}</div></div>${kOpt.m==='profil'?`<div class="lb">Tunjuk pada kad</div><div class="chs">${KF.filter(([k])=>v[k]).map(([k,l])=>`<label class="chp"><input type="checkbox" value="${k}" data-change="kField"${kOpt.f.includes(k)?' checked':''}><span>${l}</span></label>`).join('')}</div>`:''}<p class="mute">No. microchip dan maklumat vet tidak pernah dimasukkan dalam kad.</p><div class="kb2"><button class="btn g" data-action="kSave">Simpan gambar</button><button class="btn" data-action="kShare">Kongsi</button></div>`);kFit()}
function kField(el){const k=el.value;if(!KF.some(x=>x[0]===k))return;kOpt.f=el.checked?[...new Set([...kOpt.f,k])]:kOpt.f.filter(x=>x!==k);const p=$('.kps'),c=cat(kOpt.id);if(p&&c){p.innerHTML=kcard(c,kOpt);tx(p)}}
function kMode(m){if(!['profil','lahir','bela'].includes(m))return;kOpt.m=m;cardForm(kOpt.id)}
async function kImg(){const c=cat(kOpt.id);if(!c)throw new Error('no cat');await loadJs(PDF_LIBS[0].url,PDF_LIBS[0].integrity);if(typeof html2canvas!=='function')throw new Error('Pustaka PDF belum tersedia');
const box=document.createElement('div');box.id='kpb';box.innerHTML=kcard(c,kOpt);document.body.appendChild(box);tx(box);
try{if(document.fonts)await document.fonts.ready;const cv=await html2canvas(box.firstChild,{scale:1,width:1080,height:1350,backgroundColor:'#FFFFFF',scrollX:0,scrollY:0});
const b=await new Promise((ok,no)=>cv.toBlob(x=>x?ok(x):no(new Error('blob')),'image/png'));return{b,name:'kucingku-'+(c.name||'kucing').replace(/[^\w-]+/g,'-')+(kOpt.m==='lahir'?'-hari-lahir':kOpt.m==='bela'?'-hari-dibela':'')+'.png'}}finally{box.remove()}}
async function kOut(share){if(kBusy)return;kBusy=true;toast('Menyediakan gambar...');
try{const {b,name}=await kImg(),f=shareFile(b,name);
if(share&&f){try{await navigator.share({files:[f]});toast('Gambar sedia untuk dikongsi');return}catch(e){if(e&&e.name==='AbortError')return}}
const dl=await getDl();if(!dl){toast('Export tidak tersedia di sini');return}const how=await dl.save({filename:name,data:b});toast(how==='shared'?'Gambar sedia untuk dikongsi':'Gambar disimpan')}
catch(e){if(!(e&&e.code==='declined'))toast('Gagal menyediakan gambar. Cuba lagi.')}finally{kBusy=false}}

