const CUP='<path d="M4 9h12v6a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5zM16 10h1.5a2.5 2.5 0 0 1 0 5H16M8 3c0 1-1 1.5-1 2.5S8 7 8 7M12 3c0 1-1 1.5-1 2.5S12 7 12 7"/>';
