// Kemas kini app & senarai perubahan (v1.9.1). Sumber tunggal: changelog.json (BM + EN).
let CL=null,clLoad=null,swReg=null,updW=null,updV=null,updLater=false,updGo=false,updAt=0,updOpen=false;
const vGt=(a,b)=>{const x=String(a).split('.').map(Number),y=String(b).split('.').map(Number);for(let i=0;i<3;i++)if((x[i]||0)!==(y[i]||0))return (x[i]||0)>(y[i]||0);return false};
function clGet(){if(CL)return Promise.resolve(CL);if(typeof fetch!=='function')return Promise.resolve(null);if(!clLoad)clLoad=fetch('changelog.json',{cache:'no-store'}).then(r=>r.ok?r.json():Promise.reject()).then(d=>{if(!Array.isArray(d))throw 0;CL=d.filter(e=>e&&/^\d+\.\d+\.\d+$/.test(e.v)&&Array.isArray(e.i));return CL}).catch(()=>{clLoad=null;return null});return clLoad}
