function saveRec(e,id,t){e.preventDefault();t=t||tab;const o=Object.fromEntries(new FormData(e.target));if(t==='berat'){o.val=wG(o,'val');delete o.val_u}const error=recError(o,t);if(error){toast(error);return}if(o.cost!==undefined){const k=Number(o.cost);if(k>0)o.cost=Math.round(k*100)/100;else delete o.cost}if(!o.clinic)delete o.clinic;if(!o.time)delete o.time;if(t==='vaksin'&&o.first)o.first=true;else delete o.first;if(id){const r=S.recs.find(x=>x.id===id);['name','next','note','val','clinic','cost','time','first'].forEach(k=>delete r[k]);Object.assign(r,o)}else S.recs.push({id:uid(),cat:cid,type:t,...o});if(!save())return;closeSh();render();toast(id?'Rekod dikemas kini':'Rekod disimpan')}
